{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Physostigmine, a carbamate cholinesterase inhibitor with high transferability to the query, is reported to have poor oral bioavailability in patients, directly supporting a low F prediction for this carbamate-containing quaternary ammonium.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Agomelatine has an absolute oral bioavailability of <5% at therapeutic doses in humans, and the high transfer score indicates that low systemic exposure is a relevant outcome for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Tilidine systemic availability in healthy volunteers is only about 6%, with high transferability, supporting the conclusion that extensive first-pass or absorption limitations can keep F well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "BMS-187745 showed a mean absolute bioavailability of 2.6% after oral solution administration in healthy subjects, providing high-transfer human evidence for low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Acamprosate has an average oral bioavailability of about 11% under fasting conditions in humans, another high-transfer example of a small polar drug failing to reach the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low: the query is a small quaternary ammonium carbamate with a permanent positive charge and low lipophilicity, and all high-transfer experimental analogues show absolute oral bioavailability below 20%, mostly below 10%, including the carbamate physostigmine. The physicochemical prior is mixed, but the transferable experimental evidence strongly favors F < 20%.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact quaternary ammonium carbamate query is included; all evidence comes from close-transfer analogues rather than the query itself.",
    "The dominant mechanism limiting F in the query (permeability vs first-pass metabolism) is inferred from analogues rather than directly measured.",
    "No human pharmacokinetic data for pyridostigmine itself are present in the supplied evidence set."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

